export default function SlaSettings({ value, onChange }) {
  const levels = ['Urgent', 'High', 'Medium', 'Low'];
  return (
    <form>
      {levels.map((l) => (
        <label key={l}>{l} (hours)
          <input type="number" min="1" value={value[l] ?? ''} onChange={(e) => onChange({ ...value, [l]: Number(e.target.value) })} />
        </label>
      ))}
    </form>
  );
}

from app.mailer import send_email
from app.models import Ticket


def run(now):
    for t in Ticket.open_tickets():
        if t.sla_deadline and now >= t.sla_deadline and not t.breach_notified:
            send_email(t.assignee.email, f'SLA breached: {t.subject}', t.url)
            t.mark_breach_notified()

export default function ExportButton({ isAdmin }) {
  if (!isAdmin) return null;
  return <a className="btn" href="/api/tickets/export" download>Export CSV</a>;
}

def search_query(q, page, size=25):
    return (q.order_by('created_at', 'id')
             .offset((page - 1) * size)
             .limit(size))
